const params=new URLSearchParams(location.search),form=params.get('form')==='services'?'services':'life';
const source=CSLBook[form],$=id=>document.getElementById(id),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let activity=params.has('activity')?Number(params.get('activity')):-1;if(!Number.isInteger(activity)||activity< -1||activity>=source.length)activity=-1;
let view='overview',step=0,timer=null,lastEvidence='',inMemory={},reviewPage=null;
const isIcon=src=>(CSLBook.icons||[]).includes(src);
const key='skillos.csl8.workbook.'+form+'.v1';try{inMemory=JSON.parse(localStorage.getItem(key)||'{}')}catch{}
const title=form==='life'?'Pollinator Paradise — The School Ecosystem Challenge':'Event Management — The School Event Challenge';
$('title').textContent=title;$('boundary').textContent='Original Class 8 workbook · No outside pictures or sample outcomes.';
function state(){return inMemory[activity]||(inMemory[activity]={fields:{},reflection:'',step:0})}
function persist(){try{localStorage.setItem(key,JSON.stringify(inMemory));return true}catch{return false}}
function stop(){clearInterval(timer);timer=null;window.speechSynthesis?.cancel()}
function feedback(t){const el=$('feedback');if(el)el.textContent=t;lastEvidence=t}
function image(src,alt='Original workbook illustration'){return '<img class="original-figure '+(isIcon(src)?'source-icon':'')+'" src="'+src+'" alt="'+esc(alt)+'">'}
function paragraph(b){const t=b.text||'';return (b.images||[]).map(i=>image(i)).join('')+(t?'<p>'+esc(t)+'</p>':'')}
function blocks(items){return items.map(b=>b.kind==='table'?'<div class="table-scroll"><table>'+b.rows.map((r,i)=>'<tr>'+r.map(c=>'<'+(i?'td':'th')+'>'+c.images.map(x=>image(x)).join('')+esc(c.text)+'</'+(i?'td':'th')+'>').join('')+'</tr>').join('')+'</table></div>':paragraph(b)).join('')}
const field=(id,label,type='text',value='')=>'<label>'+esc(label)+'<input id="'+id+'" data-field="'+id+'" type="'+type+'" value="'+esc(state().fields[id]??value)+'" '+(type==='number'?'min="0"':'')+'></label>';
const notes=(id,label)=>'<label>'+esc(label)+'<textarea data-field="'+id+'">'+esc(state().fields[id]||'')+'</textarea></label>';
function bindFields(){document.querySelectorAll('[data-field]').forEach(e=>{if(e.type==='checkbox')e.checked=Boolean(state().fields[e.dataset.field]);e.oninput=()=>{state().fields[e.dataset.field]=e.type==='checkbox'?e.checked:e.value;persist()}})}
function checkbox(id,label){return '<label class="check"><input type="checkbox" data-field="'+id+'">'+esc(label)+'</label>'}
function current(){return source[activity]}
function openPage(n){const allowed=activity<0?(form==='life'?[6,7,8,9,10,11,12]:[79,80,81,82,83]):current().sourcePages;$('dialog-page').innerHTML=allowed.map(p=>'<option '+(p===n?'selected':'')+'>'+p+'</option>').join('');$('page-image').src='book/page-'+n+'.webp';$('page-image').alt='Original Class 8 workbook page '+n;$('page-dialog').showModal()}
$('dialog-page').onchange=()=>{$('page-image').src='book/page-'+$('dialog-page').value+'.webp';$('page-image').alt='Original Class 8 workbook page '+$('dialog-page').value};$('close-page').onclick=()=>{$('page-dialog').close();if(document.fullscreenElement)document.exitFullscreen?.()};$('fullscreen').onclick=()=>{$('page-dialog').requestFullscreen?.().catch(()=>{})};
function render(){stop();lastEvidence='';$('activities').innerHTML=['Meet the Lab',...source.map(a=>a.title.replace(/^ACTIVITY\s+\d+\s+/i,''))].map((t,i)=>'<button data-activity="'+(i-1)+'" aria-current="'+(activity===i-1)+'">'+(i?i+' · ':'')+esc(t)+'</button>').join('');document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>{activity=Number(b.dataset.activity);step=state().step||0;view='overview';history.replaceState(null,'','?form='+form+'&activity='+activity);render()});$('activity-title').textContent=activity<0?'Meet the Lab':current().title;$('page').textContent=activity<0?'WORKBOOK TOOLKIT':('ORIGINAL WORKBOOK · PAGES '+current().sourcePages[0]+'–'+current().sourcePages.at(-1));$('mission').textContent=activity<0?'Know your materials before you begin.':(current().overview[2]?.text||'');$('reflection').value=state().reflection||'';$('save-status').textContent='';$('view-tabs').innerHTML=activity<0?'':['overview','steps','records','pages'].map(v=>'<button data-view="'+v+'" aria-current="'+(view===v)+'">'+({overview:'Project overview',steps:'Follow picture steps',records:'My records',pages:'Original pages'}[v])+'</button>').join('');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});if(activity<0)meet();else if(view==='overview')overview();else if(view==='steps')stepView();else if(view==='records')records();else pagesView();bindFields();document.querySelectorAll('[data-open-page]').forEach(b=>b.onclick=()=>openPage(+b.dataset.openPage))}
function overview(){$('workspace').innerHTML='<section class="card source-overview">'+blocks(current().overview.slice(3))+'<button id="begin">Follow the workbook’s picture steps →</button></section>';$('begin').onclick=()=>{view='steps';step=0;state().step=0;render()}}
function meet(){const list=CSLBook.toolkit[form];$('workspace').innerHTML='<div class="meet-grid"><section class="card"><h2>'+(form==='life'?'MEET YOUR HABITAT TOOLKIT':'MEET THE EVENT TOOLKIT')+'</h2><div class="parts">'+list.map((t,i)=>'<button data-tool="'+i+'" aria-pressed="false">'+(t.image?image(t.image,t.name):'')+'<strong>'+esc(t.name)+'</strong></button>').join('')+'</div></section><section class="card selected-tool"><div id="tool-picture"></div><h2 id="tool-name">Select an item</h2><p id="tool-usage">Its original workbook description will appear here.</p><p id="tool-when"></p><button id="listen" disabled>Listen in English</button> <button id="stop-audio" class="secondary">Stop</button><p id="audio-status" role="status"></p><button data-open-page="'+(form==='life'?11:83)+'" class="secondary">See original toolkit page</button></section></div>';let selected;document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{stop();selected=list[+b.dataset.tool];document.querySelectorAll('[data-tool]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('tool-name').textContent=selected.name;$('tool-usage').textContent=selected.usage;$('tool-when').textContent=selected.when;$('tool-picture').innerHTML=selected.image?image(selected.image,selected.name):'';$('listen').disabled=!window.speechSynthesis||!window.SpeechSynthesisUtterance});$('listen').onclick=()=>{stop();const spoken=new SpeechSynthesisUtterance(selected.name+'. '+selected.usage+'. '+selected.when);spoken.lang='en-IN';spoken.onerror=()=>{$('audio-status').textContent='Audio is unavailable. Read the workbook description above.'};window.speechSynthesis.speak(spoken)};$('stop-audio').onclick=stop}
function stepView(){const a=current();step=Math.min(step,a.steps.length-1);if(step<0){$('workspace').innerHTML='<section class="card">'+blocks(a.pages[1]||a.overview)+'</section>';return}const s=a.steps[step];let figure=s.blocks.flatMap(b=>b.images||[]).find(img=>!isIcon(img))||s.pageFigure;const body=s.blocks.map(b=>b.kind==='paragraph'?{...b,images:[]}:b).filter(b=>b.text||b.kind==='table');$('workspace').innerHTML='<div class="step-layout"><aside class="card step-list"><h3>Workbook sequence</h3>'+a.steps.map((t,i)=>'<button data-step="'+i+'" aria-current="'+(i===step)+'">'+'<small>Page '+t.page+'</small>'+esc(t.title)+'</button>').join('')+'</aside><div><section class="card source-stage"><div class="source-bar"><span>ORIGINAL ARTWORK · PAGE '+s.page+'</span><button class="secondary" data-open-page="'+s.page+'">Enlarge original page</button></div><h2>'+esc(s.title)+'</h2>'+(figure?'<div class="picture-stage" id="picture-stage">'+image(figure,s.title)+'<div id="motion-layer"></div></div>':'')+'<div class="source-instructions">'+blocks(body)+'</div><div class="step-actions"><button id="previous" class="secondary" '+(step===0?'disabled':'')+'>← Previous step</button><span>Step '+(step+1)+' of '+a.steps.length+'</span><button id="next" '+(step===a.steps.length-1?'disabled':'')+'>Next step →</button></div></section><section class="card interaction"><span class="eyebrow">INTERACTIVE WORKBOOK DESK</span><div id="desk"></div><div id="feedback" class="feedback" role="status">Use the workbook step and record what you actually observe.</div></section></div></div>';document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=+b.dataset.step;state().step=step;persist();render()});$('previous').onclick=()=>{step--;state().step=step;persist();render()};$('next').onclick=()=>{step++;state().step=step;persist();render()};if(form==='life')lifeDesk();else eventDesk()}
function records(){const a=current();$('workspace').innerHTML='<section class="card"><h2>Record your own work</h2><p>The prompts and tables below are copied from this activity’s workbook pages. Source examples remain labelled MODEL ONLY. Staff confirmation remains a real-world staff task.</p>'+a.pages.map((pg,pi)=>'<details class="record-page" '+(pi===a.pages.findIndex(page=>/LOGBOOK|RECORD|OUR.*LOG|PROPOSAL/.test(page[1]?.text||''))?'open':'')+'><summary>Page '+a.sourcePages[pi]+' · '+esc(pg[1]?.text||'')+'</summary>'+editable(pg.slice(2),'p'+a.sourcePages[pi])+'</details>').join('')+'</section>'}
function editable(items,prefix){return items.map((b,i)=>{if(b.kind==='table')return '<div class="table-scroll"><table>'+b.rows.map((row,ri)=>'<tr>'+row.map((c,ci)=>'<'+(ri?'td':'th')+'>'+c.images.map(x=>image(x)).join('')+(c.text.includes('___')?'<label><span>'+esc(c.text.replace(/_{3,}/g,' [record] '))+'</span><textarea aria-label="Page record row '+ri+' column '+ci+'" data-field="'+prefix+'-'+i+'-'+ri+'-'+ci+'">'+esc(state().fields[prefix+'-'+i+'-'+ri+'-'+ci]||'')+'</textarea></label>':esc(c.text))+'</'+(ri?'td':'th')+'>').join('')+'</tr>').join('')+'</table></div>';let t=b.text||'';if(t.includes('___'))return notes(prefix+'-'+i,t.replace(/_{3,}/g,' [record] '));if(t.startsWith('□'))return t.split('□').map((label,j)=>label.trim()?checkbox(prefix+'-'+i+'-'+j,label.trim()):'').join('');return paragraph(b)}).join('')}
function pagesView(){$('workspace').innerHTML='<section class="card"><h2>Original workbook pages</h2><p>These are the original pages rendered from your Class 8 Word workbook, with their artwork and wording unchanged. Select a page to enlarge it.</p><div class="page-thumbs">'+current().sourcePages.map(n=>'<button data-open-page="'+n+'"><img loading="lazy" src="book/page-'+n+'.webp" alt="Original workbook page '+n+'"><span>Page '+n+'</span></button>').join('')+'</div></section>'}
function desk(html){$('desk').innerHTML=html}
function desk(html){$('desk').innerHTML=html+'<details class="source-task"><summary>Complete this step’s original workbook prompts</summary>'+editable(current().steps[step].blocks,'step-'+step)+'</details>'}
function general(){desk(notes('step-'+step+'-work','My work / evidence for this workbook step')+notes('step-'+step+'-check','What is checked, uncertain or pending?'))}
function lifeDesk(){
 if(activity===0&&step===2){desk('<h3>Measure and check</h3>'+field('length','Accessible length','number')+field('width','Accessible width','number')+'<label>Matching unit<select id="unit"><option>metres</option><option>centimetres</option></select></label><label>Bed shape<select id="shape"><option value="">Choose after observing</option><option value="rectangle">Rectangular</option><option value="irregular">Irregular</option></select></label><button id="area">Estimate rectangular area</button>');$('area').onclick=()=>{if($('length').value===''||$('width').value===''){feedback('Record your own measurements and consistent units first.');return}feedback($('shape').value==='rectangle'?'Your rectangular estimate: '+CSLModel.area(+$('length').value,+$('width').value)+' square '+$('unit').value+'. Check both readings with your teammate.':'For an irregular bed, sketch it without pretending length × width gives its exact area.')}}
 else if(activity===1&&step===1){const reference=current().pages.flatMap(pg=>pg).flatMap(b=>b.kind==='table'?b.rows:[]).filter(row=>row.some(c=>/bee|fly|butterfly|beetle|unknown/i.test(c.text)));desk('<h3>Describe first; check before naming</h3>'+notes('visitor-clue','Visible body shape, wings, antennae and behaviour')+notes('visitor-group','Suggested broad group / tentative or checked with help')+(reference.length?blocks([{kind:'table',rows:reference}]):'')+'<button id="visitor-limit">Check what the record can establish</button>');$('visitor-limit').onclick=()=>feedback('Use “bee-like”, “fly-like” or “unknown” when evidence is limited. Observation rows are not a count of different animals or species.')}
 else if(activity===2){pollination()}
 else if(activity===3&&(step===1||step===2)){watchDesk('baseline')}
 else if(activity===3&&step===4){meanDesk(false)}
 else if(activity===4&&step===3){desk('<h3>Compare two possible priorities</h3>'+notes('concern-a','Concern A / supporting page, row or date')+notes('concern-b','Concern B / supporting page, row or date')+notes('priority-use','Likely usefulness, feasible care and school permission')+notes('priority-uncertainty','What still needs checking?')+'<button id="priority-check">Review the evidence rule</button>');$('priority-check').onclick=()=>feedback('Do not give an unsupported concern a higher priority simply because it sounds impressive. Ask the teacher to check your reasoning; purchasing and planting come later.')}
 else if(activity===5&&step===3){budgetDesk()}
 else if(activity===6&&step===2){desk('<h3>Follow the original planting diagram</h3>'+checkbox('spacing','Gardener checked mature spacing and plant-specific instructions.')+checkbox('rootball','Support the root ball; do not pull the stem.')+checkbox('depth','Use the advised growing depth.')+'<button id="plant-check">Check before proceeding</button>');$('plant-check').onclick=()=>feedback('Ask the adult to check before proceeding. The diagram is schematic; spacing is not a recommendation. Keep the gardener’s plant-specific instructions.')}
 else if(activity===7&&step===2){desk('<h3>Care check, then record</h3>'+field('plant-id','Plant ID')+notes('plant-condition','Observed plant / soil condition')+notes('care-action','Action, reason and next check under the gardener’s method')+'<button id="care-check">Review care boundary</button>');$('care-check').onclick=()=>feedback('Ask before changing care. Keep care actions separate from timed watches; do not water, weed or handle plants during a watch.')}
 else if(activity===7&&(step===1||step===3)){watchDesk('follow-up')}
 else if(activity===8&&(step===1||step===2)){meanDesk(true)}
 else if(activity===9&&step===4){desk('<h3>Handover stays pending until it happens</h3>'+notes('habitat-receiver','Receiving staff role and actual acceptance, or pending')+notes('habitat-care','Care rota, backup and next review')+notes('habitat-open','Outstanding question / accepted responsibility'))}
 else general();
}
function pollination(){desk('<h3>Paper pollen · classroom model</h3><p>Use the number of dots agreed with your teacher. Flower A is the source; flower B’s target represents the stigma. This rehearses the paper model, not fertilisation or real flower success.</p>'+field('pollen-source','Agreed source dots','number')+field('pollen-carried','Dots loaded in paper visitor’s pocket','number')+'<div class="pollen-board"><section><h4>A · source</h4><div id="source-dots"></div></section><section id="paper-carrier"><h4>Paper visitor</h4><span id="pocket-count">Pocket empty</span></section><section><h4>B · target</h4><div id="target-dots"></div></section></div><button id="no-transfer">Run no-transfer comparison</button> <button id="load-pocket" class="secondary">Load paper pocket</button> <button id="transfer" disabled>Move A → B and place dots</button><p class="fine">Keep a row for every trial in My records. Reset before each new trial.</p>');let loaded=0,sourceDots=0;const dots=n=>Array.from({length:Math.min(n,100)},()=>'<span class="paper-dot"></span>').join('')+(n>100?'<small>Count: '+n+'</small>':'');function read(){const n=+$('pollen-source').value,c=+$('pollen-carried').value;if($('pollen-source').value===''||!Number.isInteger(n)||n<0){feedback('Enter the agreed whole-number source count.');return null}return {n,c}}$('no-transfer').onclick=()=>{const v=read();if(!v)return;sourceDots=v.n;loaded=0;$('source-dots').innerHTML=dots(v.n);$('target-dots').innerHTML='0 dots';$('pocket-count').textContent='Pocket empty';$('transfer').disabled=true;feedback('No-transfer comparison: leave all dots on A; do not move the carrier or dots between cards. B’s target has zero dots in this classroom comparison.')};$('load-pocket').onclick=()=>{const v=read();if(!v)return;if($('pollen-carried').value===''||!Number.isInteger(v.c)||v.c<0||v.c>v.n){feedback('Record a whole-number pocket count from the available source dots.');return}sourceDots=v.n;loaded=v.c;$('source-dots').innerHTML=dots(v.n-v.c);$('target-dots').innerHTML='0 dots';$('pocket-count').textContent=v.c+' dots in pocket';$('transfer').disabled=false;feedback('Both cards are reset. Carry the loaded dots from A to B; place them on the target.')};$('transfer').onclick=()=>{const r=CSLModel.transfer(sourceDots,loaded);$('source-dots').innerHTML=dots(r.remaining);$('target-dots').innerHTML=dots(r.target);$('paper-carrier').classList.add('move-carrier');$('pocket-count').textContent='Pocket empty';$('transfer').disabled=true;feedback('Paper trial: source '+sourceDots+'; target '+r.target+'; remaining on A '+r.remaining+'. Record any dots elsewhere in your physical trial. Name a limitation: this models pollen transfer, not fertilisation, fruit or seed formation.')};}
function watchDesk(series){desk('<h3>'+ (series==='baseline'?'Baseline':'Follow-up')+' watch rehearsal</h3><p>Keep practice counts separate from real data. Use the workbook’s arrival rule and a full ten-minute watch.</p><button id="watch-start">Start ten-minute timer</button> <button id="watch-pause" class="secondary" disabled>Pause / mark interrupted</button><p id="watch-clock">10:00 · ready</p><div class="metrics"><div class="metric">Practice visit events<b id="visit-count">0</b></div></div><button id="new-arrival">Arrives from outside and lands</button> <button id="same-visitor" class="secondary">Moves between flowers without leaving</button>'+notes('watch-rule','Patch, observer, flower-count unit and conditions')+notes('watch-issue','Interruption, observer change or recent care'));let secs=600,count=0,interrupted=false;$('new-arrival').onclick=()=>{$('visit-count').textContent=++count;feedback('One qualifying arrival event added to the practice tally. This is not a count of unique insects or successful pollination.')};$('same-visitor').onclick=()=>feedback('Do not add another arrival for movement between flowers without leaving the patch. Keep the agreed counting rule.');function tick(){secs--;$('watch-clock').textContent=Math.floor(secs/60)+':'+String(secs%60).padStart(2,'0');if(secs<=0){stop();$('watch-pause').disabled=true;feedback(interrupted?'The rehearsal was interrupted. Keep the reason; do not treat an interrupted watch as zero or silently shorten it.':'Ten-minute browser rehearsal finished. It is practice, not a real field observation. Use real watch sheets for your baseline or follow-up.')}}$('watch-start').onclick=()=>{stop();secs=600;interrupted=false;count=0;$('visit-count').textContent='0';$('watch-pause').disabled=false;$('watch-pause').textContent='Pause / mark interrupted';timer=setInterval(tick,1000);feedback('Timer started. Count only the events you select for this rehearsal; no visitors are generated. Actual watches use your teacher-approved patch.')};$('watch-pause').onclick=()=>{interrupted=true;if(timer){stop();$('watch-pause').textContent='Resume rehearsal';feedback('Interruption recorded for this rehearsal. In real fieldwork keep the interrupted record and repeat a full valid watch if possible.')}else{timer=setInterval(tick,1000);$('watch-pause').textContent='Pause / mark interrupted'}}}
function meanDesk(compare){const series=compare?['Baseline','Follow-up']:['Baseline'];desk('<h3>Use valid, equal-duration watch totals</h3><p>Enter real counts only. Valid zeros stay in the mean. Mark interrupted or unavailable watches invalid; do not turn them into zero.</p>'+series.map((s,j)=>'<h4>'+s+'</h4>'+[1,2,3].map((n,i)=>'<div class="watch-row">'+field('watch-'+j+'-'+i,'Watch '+n+' visits','number')+checkbox('valid-'+j+'-'+i,'Valid full 10-minute watch')+'</div>').join('')).join('')+'<button id="means">Calculate from my records</button><div class="metrics" id="means-result"></div><div id="watch-chart" class="watch-chart"></div>'+notes('comparison-limits','Conditions, limitations and alternative explanations'));$('means').onclick=()=>{const results=series.map((_,j)=>CSLModel.mean([0,1,2].filter(i=>state().fields['valid-'+j+'-'+i]).map(i=>$('watch-'+j+'-'+i).value)));if(results.some(r=>r.n===0)){feedback('At least one series has no valid recorded counts. Report no mean and identify the missing evidence.');return}const max=Math.max(...results.map(r=>r.value),1);$('means-result').innerHTML=results.map((r,i)=>'<div class="metric">'+series[i]+'<b>'+r.value.toFixed(2)+'</b>visits / 10 minutes · n = '+r.n+'</div>').join('');$('watch-chart').innerHTML=results.map((r,i)=>'<div><span>'+series[i]+'</span><div class="chart-bar" style="width:'+r.value/max*100+'%">'+r.value.toFixed(2)+'</div></div>').join('')+'<small>Bar axis begins at zero · compare means alongside original records.</small>';feedback(compare?'Follow-up mean minus baseline mean = '+(results[1].value-results[0].value).toFixed(2)+' visits per 10-minute watch. Compare flowering, weather, observer changes and care history; this does not prove an ecological benefit.':'Mean recorded visits = '+results[0].value.toFixed(2)+' per 10-minute watch; n = '+results[0].n+'. State the method, conditions and limits.')};}
function budgetDesk(){desk('<h3>Build and check your estimate</h3><p>Enter quantities and dated price evidence from your own plan. Reused resources can be zero new cash. Estimates are separate from actual paid costs.</p><div class="table-scroll"><table><tr><th>Resource</th><th>Quantity</th><th>Unit price ₹</th></tr>'+[0,1,2,3].map(i=>'<tr><td>'+field('item-'+i,'Resource '+(i+1))+'</td><td>'+field('qty-'+i,'Quantity '+(i+1),'number')+'</td><td>'+field('price-'+i,'Unit price '+(i+1),'number')+'</td></tr>').join('')+'</table></div>'+field('delivery','Delivery / approved extra costs ₹','number')+(form==='life'?field('reserve','Teacher-agreed reserve ₹','number'):'')+field('allocation','Confirmed spending limit ₹','number')+'<button id="budget">Check the arithmetic</button><div id="budget-total" class="metrics"></div>'+notes('price-source','Source / date / estimate or quotation / pending checks'));$('budget').onclick=()=>{const rows=[];for(let i=0;i<4;i++){if(!$('item-'+i).value&&!$('qty-'+i).value&&!$('price-'+i).value)continue;if($('qty-'+i).value===''||$('price-'+i).value===''||+$('qty-'+i).value<0||+$('price-'+i).value<0){feedback('Each used line needs a non-negative quantity and unit price. Record zero for confirmed reused resources, not for an unknown price.');return}rows.push({quantity:+$('qty-'+i).value,price:+$('price-'+i).value})}if(!rows.length){feedback('Enter at least one resource with checked quantity and price evidence.');return}const total=CSLModel.budget(rows,+$('delivery').value||0,$('reserve')?(+$('reserve').value||0):0);$('budget-total').innerHTML='<div class="metric">Proposed estimate<b>₹'+total.toFixed(2)+'</b></div>';feedback($('allocation').value===''?'Estimate calculated. A confirmed spending limit is still pending. This is not approval to purchase.':total>+$('allocation').value?'Estimate exceeds the entered limit. Revise through reducing, reusing or replacing resources without removing essential access or safety arrangements.':'Estimate is within the entered limit. School review and purchasing authorisation still remain separate.')};}
function eventDesk(){
 if(activity===0&&step===3){desk('<h3>Write the event brief from checked facts</h3>'+notes('event-purpose','Purpose and intended outcome')+field('event-audience','Intended audience / scale')+field('event-date','Proposed or confirmed date','date')+field('event-venue','Venue / school limits')+notes('event-pending','Pending decisions / responsible school adult'))}
 else if(activity===1&&(step===1||step===2)){desk('<h3>Visitor inquiry · no invented respondents</h3>'+notes('inquiry-questions','Questions to prepare and pilot')+notes('inquiry-voices','Relevant viewpoints / teacher-approved inquiry arrangement')+field('conversation-count','Actual short conversations completed','number')+notes('visitor-quotes','Anonymous response codes / exact words or labelled summaries')+'<button id="inquiry-review">Check what this inquiry represents</button>');$('inquiry-review').onclick=()=>feedback('The book suggests 4–6 short conversations per team, adjusted by the teacher. A small inquiry informs planning; it does not represent every visitor. Flag missing voices.')}
 else if(activity===2&&(step===2||step===3)){desk('<h3>Responsibility and handover rehearsal</h3>'+field('handover-task','Real task from the event brief')+field('task-owner','Owner / role')+field('task-backup','Backup / cover')+field('task-deadline','Agreed deadline')+notes('handover-message','Task status / next action / what the receiver needs')+'<button id="handover-read">Show the receiver’s check</button>'+notes('receiver-repeat','Receiver’s own repeat-back / question'));$('handover-read').onclick=()=>feedback('Test the actual handover with a teammate. Check that the receiver understands the current status, next action and responsibility; record the difficulty and revision.')}
 else if(activity===3&&(step===2||step===3)){layoutDesk()}
 else if(activity===4&&step===2){sequenceDesk()}
 else if(activity===4&&step===3){budgetDesk()}
 else if(activity===5&&(step===1||step===2)){invitationDesk()}
 else if(activity===6&&(step===2||step===3)){arrivalDesk()}
 else if(activity===7&&step===3){desk('<h3>Tabletop test · communication and decisions</h3><label>Workbook problem to discuss<select id="problem"><option>A session is late</option><option>A duty member is absent</option><option>A promised item is unavailable</option><option>A sign is outdated</option><option>Weather affects the venue</option></select></label>'+notes('problem-evidence','Actual observation or unresolved check supporting this problem')+notes('problem-alternative','Feasible school-approved alternative / person with authority')+notes('problem-message','Who needs the updated decision and how will they receive it?')+'<button id="tabletop">Review the student boundary</button>');$('tabletop').onclick=()=>feedback('Test decisions at a table. Do not create a hazard, block an exit, disconnect power, sound an alarm or stage an injury. The responsible school adult makes the relevant decision.')}
 else if(activity===8&&(step===1||step===2)){readinessDesk()}
 else if(activity===8&&step===3){desk('<h3>Actual event evidence is separate</h3>'+notes('actual-event','Actual event date / venue / supervising role, or not yet undertaken')+notes('actual-work','My actual work / original evidence reference')+notes('actual-change','Approved change / reason / adult / time / people informed')+'<p>Browser rehearsal does not mark delivery complete. Use the original event-day records only when the real event happens.</p>')}
 else if(activity===9&&step===1){reconcileDesk()}
 else if(activity===9&&step===4){desk('<h3>Complete the real handover</h3>'+notes('event-receiver','Receiving role / acceptance date, or pending')+notes('event-resources','Reusable materials / condition / return record')+notes('event-costs','Outstanding return or approved unpaid cost / accepted owner')+notes('event-review','Record storage reference / next action / review date')+'<p>Do not state that the project is financially closed while an approved cost remains unsettled.</p>')}
 else general();
}
function sequenceDesk(){let order=['Setup','Returns','Approvals','Event','Preparation','Clearing'];desk('<h3>Put task cards in the workbook order</h3><p>Identify dependencies and allow transition time. Actual dates and task owners belong in the original timetable record.</p><div id="task-cards" class="task-cards"></div><button id="sequence-check">Check sequence</button>');function draw(){$('task-cards').innerHTML=order.map((n,i)=>'<div><strong>'+n+'</strong><button data-up="'+i+'" class="secondary" '+(i===0?'disabled':'')+' aria-label="Move '+n+' earlier">↑</button><button data-down="'+i+'" class="secondary" '+(i===order.length-1?'disabled':'')+' aria-label="Move '+n+' later">↓</button></div>').join('');document.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>{const i=+b.dataset.up;[order[i-1],order[i]]=[order[i],order[i-1]];draw()});document.querySelectorAll('[data-down]').forEach(b=>b.onclick=()=>{const i=+b.dataset.down;[order[i+1],order[i]]=[order[i],order[i+1]];draw()})}draw();$('sequence-check').onclick=()=>feedback(order.join('|')==='Approvals|Preparation|Setup|Event|Clearing|Returns'?'The workbook sequence is in order. Now give actual tasks a start, finish and owner; check clashes and dependencies.':'Use the workbook sequence: approvals, preparation, setup, event, clearing and returns. Check which task depends on another.')}
function layoutDesk(){desk('<h3>Draft your visitor-journey plan</h3><p>The plan below is learner-created. It is not a new school map or a confirmed room-capacity plan. Use actual measurements and the school’s approved routes.</p>'+field('layout-label','Feature label / visitor need')+'<button id="add-marker">Add my labelled feature</button> <button id="clear-markers" class="secondary">Clear this draft layout</button><div class="learner-layout" id="learner-layout" role="group" aria-label="Learner-created draft layout"></div><p>Click a feature, then click its new place to move it. The drawing is not to scale.</p>'+notes('journey-trial','Partner’s journey test / unclear position / access concern')+notes('layout-revision','Change after trial and required school checks'));let markers=state().fields['layout-markers']||[],selected=null;const board=$('learner-layout');function draw(){board.innerHTML=markers.map((m,i)=>'<button data-marker="'+i+'" style="left:'+m.x+'%;top:'+m.y+'%" aria-pressed="'+(selected===i)+'">'+esc(m.label)+'</button>').join('');board.querySelectorAll('[data-marker]').forEach(b=>b.onclick=e=>{e.stopPropagation();selected=+b.dataset.marker;draw();feedback('Feature selected. Click its new place in your draft, then test the journey with a partner.')});state().fields['layout-markers']=markers;persist()}$('add-marker').onclick=()=>{const label=$('layout-label').value.trim();if(!label){feedback('Enter a label from your own measured plan first.');return}markers.push({label,x:20+markers.length%3*25,y:20+Math.floor(markers.length/3)%3*25});draw()};board.onclick=e=>{if(selected===null)return;const r=board.getBoundingClientRect();markers[selected].x=Math.min(85,Math.max(0,(e.clientX-r.left)/r.width*100));markers[selected].y=Math.min(85,Math.max(0,(e.clientY-r.top)/r.height*100));selected=null;draw()};$('clear-markers').onclick=()=>{markers=[];selected=null;draw()};draw()}
function invitationDesk(){desk('<h3>Create your own draft from confirmed information</h3>'+field('notice-purpose','Purpose / audience')+field('notice-date','Full date','date')+field('notice-time','Visitor start and finish time')+field('notice-venue','Approved venue and arrival information')+notes('notice-participation','What visitors can do / school-confirmed requirements')+notes('notice-help','School-approved help or response method, if required')+'<button id="notice-preview">Preview my draft</button><div id="notice-preview-card" class="notice-preview"></div>'+notes('reader-test','What the new reader understood / hesitated over')+notes('notice-revise','Specific revision and school review status'));$('notice-preview').onclick=()=>{$('notice-preview-card').innerHTML='<strong>DRAFT · not authorised for release</strong><h3>'+esc($('notice-purpose').value)+'</h3><p>'+esc($('notice-date').value)+' · '+esc($('notice-time').value)+'</p><p>'+esc($('notice-venue').value)+'</p><p>'+esc(state().fields['notice-participation']||'')+'</p><p>'+esc(state().fields['notice-help']||'')+'</p>';feedback('Test this draft with a reader without giving hints. Check all essential details and obtain school review before any distribution. This button sends nothing.')};}
function arrivalDesk(){desk('<h3>Anonymous practice arrival tally</h3><p>Rehearsal only. Do not add trial visitors, invitations or planned attendance to an actual event-day figure.</p>'+field('arrival-code','Anonymous arrival code')+'<button id="arrival">Record a practice entry</button><div class="metrics"><div class="metric">Recorded practice entries<b id="entries">0</b></div><div class="metric">Distinct entered codes<b id="codes">0</b></div></div><p id="arrival-log"></p>'+notes('arrival-rule','School-confirmed counting rule / return-visit check method'));let entries=0;const codes=new Set();$('arrival').onclick=()=>{const code=$('arrival-code').value.trim();if(!code){feedback('Use a fictional anonymous code for this desk rehearsal, not a personal name.');return}entries++;const repeat=codes.has(code);codes.add(code);$('entries').textContent=entries;$('codes').textContent=codes.size;$('arrival-log').textContent='Last entered code: '+code+(repeat?' · repeat code':' · first appearance of this code');feedback(repeat?'This code has appeared before. Apply the school-confirmed return-visit rule. If returns cannot be identified reliably, report recorded entries rather than claim unique visitors.':'One practice entry recorded. Distinct codes are not verified unique people; keep the agreed counting label and real event evidence separate.')};}
function readinessDesk(){const checks=['Purpose, audience, date and visitor times confirmed','Current layout, access and school safety arrangements confirmed','Duties, backups, breaks and adult support covered','Resources ready; required spending or loans authorised','Messages, signs and help information current','Clean registration, expense and feedback records ready','Contingency decisions and reporting route current'];desk('<h3>Readiness desk rehearsal</h3><p>Use ready / action needed / awaiting decision. A selection alone is not evidence; name the checked plan, school adult or corrective action.</p>'+checks.map((c,i)=>'<label>'+c+'<select id="ready'+i+'"><option value="pending">Awaiting decision</option><option value="action">Action needed</option><option value="ready">Ready — evidence recorded separately</option></select></label>').join('')+notes('readiness-evidence','Required action / responsible person / deadline / recheck result')+'<button id="readiness">Review outstanding checks</button>');$('readiness').onclick=()=>{const pending=checks.filter((_,i)=>$('ready'+i).value!=='ready').length;feedback(pending?pending+' checks need action or a decision in this rehearsal. Students report readiness; the school adult decides proceed, revise and recheck, or postpone.':'All selections say ready, but this browser cannot verify school checks or authorise opening. The responsible school adult makes the actual decision.')};}
function reconcileDesk(){desk('<h3>Keep estimate, paid and committed amounts distinct</h3>'+field('final-estimate','Final reviewed estimate ₹','number')+field('paid','Actual paid total ₹','number')+field('committed','Unpaid approved commitments ₹','number')+field('confirmed-allocation','Confirmed allocation ₹','number')+'<button id="reconcile">Calculate the checked differences</button><div class="metrics" id="reconciliation"></div>'+notes('reconcile-source','Bill references / responsible adult / date / pending reconciliation'));$('reconcile').onclick=()=>{const ids=['final-estimate','paid','committed','confirmed-allocation'];if(ids.some(id=>$(id).value===''||+$(id).value<0)){feedback('Enter all four checked non-negative amounts. Keep unconfirmed costs or allocation pending; do not invent a saving.');return}const r=CSLModel.reconcile(+$('confirmed-allocation').value,+$('paid').value,+$('committed').value,+$('final-estimate').value);$('reconciliation').innerHTML='<div class="metric">Paid minus estimate<b>₹'+r.difference.toFixed(2)+'</b></div><div class="metric">Allocation less paid and committed<b>₹'+r.remaining.toFixed(2)+'</b></div>';feedback('A negative paid-minus-estimate difference means paid costs are below the estimate so far; unpaid commitments may change the final outcome. Reconcile with the responsible school adult.')};}
$('reflection').oninput=()=>{state().reflection=$('reflection').value;persist()};
$('save').onclick=()=>{state().reflection=$('reflection').value;try{persist();const project='skillos.project.'+(form==='life'?'pollinator-8':'event-8'),record=JSON.parse(localStorage.getItem(project)||'{}');record.simulator=record.simulator||{};record.simulator[String(activity)]={activity:activity<0?'Meet the Lab':current().title,observation:state().reflection,modelFeedback:lastEvidence,workbookFields:state().fields,basis:'Class 8 original workbook v20',kind:'workbook rehearsal / learner-entered record',savedAt:new Date().toISOString()};localStorage.setItem(project,JSON.stringify(record));$('save-status').textContent='Saved to this project’s workbook notebook in this browser.'}catch{$('save-status').textContent='Could not save. Copy your record before leaving; browser storage is unavailable.'}};
$('reset').onclick=()=>{stop();render()};window.addEventListener('pagehide',stop);step=state().step||0;render();
